namespace Valora.Application.ActionCenter;

public sealed class ActionPlanService(IActionPlanRepository repository) { public Task<ActionDashboardDto> Dashboard(Guid o, Guid u, bool wide, CancellationToken c) => repository.Dashboard(o,u,wide,c); public Task<IReadOnlyList<ActionPlanDto>> List(Guid o, Guid u, bool wide, CancellationToken c) => repository.List(o,u,wide,c); public Task<Valora.Application.Workspace.PageResult<ActionPlanDto>> List(Guid o,Guid u,bool wide,ActionPlanListQuery q,CancellationToken c) { return repository.List(o,u,wide,q,c); } public Task<Valora.Application.Workspace.PageResult<ActionOptionDto>> Options(Guid o, Guid u, bool wide, Valora.Application.Workspace.OptionQuery q, CancellationToken c) => repository.Options(o,u,wide,q,c); public Task<ActionPlanDto?> Get(Guid o, Guid u, Guid id, bool wide, CancellationToken c) => repository.Get(o,u,id,wide,c); public Task<Guid> Create(Guid o, Guid u, bool global, CreateActionPlanRequest r, CancellationToken c) { Validate(r.Title, r.EvidenceSummary, r.Priority); if(string.IsNullOrWhiteSpace(r.Summary)) throw new ArgumentException("Descrição do plano é obrigatória."); if(string.IsNullOrWhiteSpace(r.ExpectedOutcome)) throw new ArgumentException("Resultado esperado é obrigatório."); if(string.IsNullOrWhiteSpace(r.CommandId)) throw new ArgumentException("A chave da criação é obrigatória."); if(r.StartsAt.HasValue&&r.DueAt.HasValue&&r.StartsAt.Value.Date>r.DueAt.Value.Date) throw new ArgumentException("O prazo não pode ser anterior ao início."); var origin=r.OriginType?.Trim().ToLowerInvariant(); if(origin is null||!System.Text.RegularExpressions.Regex.IsMatch(origin,"^(manual|diagnostic|result|ai_insight|alert|decision)$")) throw new ArgumentException("Origem inválida."); if(origin=="manual"&&r.OriginId.HasValue) throw new ArgumentException("Um plano manual não pode informar uma referência de origem."); if(origin=="diagnostic"&&(r.DiagnosticId is null||r.OriginId!=r.DiagnosticId)) throw new ArgumentException("Selecione um diagnóstico válido como origem."); if(origin=="result"&&(r.ResultId is null||r.OriginId!=r.ResultId)) throw new ArgumentException("Selecione um resultado válido como origem."); return repository.Create(o, u, global, r with { OriginType=origin }, c); } public Task Edit(Guid o,Guid u,Guid id,bool wide,EditActionPlanRequest r,CancellationToken c) { Validate(r.Title,"preservada",r.Priority); if(string.IsNullOrWhiteSpace(r.Summary)||string.IsNullOrWhiteSpace(r.ExpectedOutcome)) throw new ArgumentException("Descrição e resultado esperado são obrigatórios."); return repository.Edit(o,u,id,wide,r,c); } public Task Assign(Guid o,Guid u,Guid id,bool wide,AssignResponsibleRequest r,CancellationToken c) => repository.Assign(o,u,id,wide,r,c); public Task Reschedule(Guid o,Guid u,Guid id,bool wide,RescheduleActionRequest r,CancellationToken c) => repository.Reschedule(o,u,id,wide,r,c); internal static void Validate(string? title, string? evidence, string? priority) { if (string.IsNullOrWhiteSpace(title) || title.Trim().Length < 3) throw new ArgumentException("Título deve ter ao menos 3 caracteres."); if (title.Trim().Length > 180) throw new ArgumentException("Título deve ter no máximo 180 caracteres."); if (string.IsNullOrWhiteSpace(evidence)) throw new ArgumentException("A ação precisa indicar sua base de evidência."); if (string.IsNullOrWhiteSpace(priority) || !ActionStatuses.Priorities.Contains(priority)) throw new ArgumentException("Prioridade inválida."); } }
public sealed class ActionItemService(IActionItemRepository repository) { public Task<Valora.Application.Workspace.PageResult<ActionItemDto>> List(Guid o, Guid u, Guid? p, bool wide, ActionItemListQuery query, CancellationToken c) => repository.List(o,u,p,wide,query,c); public Task<Valora.Application.Workspace.PageResult<ActionOptionDto>> Options(Guid o, Guid u, bool wide, Valora.Application.Workspace.OptionQuery q, CancellationToken c) => repository.Options(o,u,wide,q,c); public Task<Valora.Application.Workspace.PageResult<ActionOptionDto>> VisibleResponsibleOptions(Guid o,Guid u,bool wide,Valora.Application.Workspace.OptionQuery q,CancellationToken c)=>repository.VisibleResponsibleOptions(o,u,wide,q,c); public Task<Valora.Application.Workspace.PageResult<ActionOptionDto>> ResponsibleOptions(Guid o,Valora.Application.Workspace.OptionQuery q,CancellationToken c)=>repository.ResponsibleOptions(o,q,c); public Task<ActionItemDto?> Get(Guid o, Guid u, Guid id, bool wide, CancellationToken c) => repository.Get(o,u,id,wide,c); public Task<ActionItemDetailsDto?> Details(Guid o, Guid u, Guid id, bool wide, bool manage, bool complete, int page, CancellationToken c) => repository.Details(o,u,id,wide,manage,complete,page,c); public Task<Guid> Create(Guid o, Guid u, CreateActionItemRequest r, CancellationToken c) { ActionPlanService.Validate(r.Title, r.EvidenceSummary, r.Priority); if(string.IsNullOrWhiteSpace(r.ExpectedOutcome)) throw new ArgumentException("Resultado esperado é obrigatório."); if(string.IsNullOrWhiteSpace(r.CommandId)) throw new ArgumentException("A chave da criação é obrigatória."); return repository.Create(o, u, r, c); } public Task Edit(Guid o,Guid u,Guid id,bool wide,EditActionItemRequest r,CancellationToken c) { ActionPlanService.Validate(r.Title,"preservada",r.Priority); if(string.IsNullOrWhiteSpace(r.ExpectedOutcome)) throw new ArgumentException("Resultado esperado é obrigatório."); return repository.Edit(o,u,id,wide,r,c); } public Task Assign(Guid o,Guid u,Guid id,bool wide,AssignResponsibleRequest r,CancellationToken c) => repository.Assign(o,u,id,wide,r,c); public Task Reschedule(Guid o,Guid u,Guid id,bool wide,RescheduleActionRequest r,CancellationToken c) => repository.Reschedule(o,u,id,wide,r,c); }
public sealed class PriorityActionService(IPriorityActionRepository repository) {
    public Task<IReadOnlyList<PriorityActionDto>> List(Guid o, Guid priority, Guid u, bool wide, CancellationToken c) => repository.List(o, priority, u, wide, c);
    public Task<Guid> Link(Guid o, Guid u, Guid priority, LinkPriorityActionRequest r, bool wide, CancellationToken c) { if (r.ActionId==Guid.Empty || string.IsNullOrWhiteSpace(r.CommandId)) throw new ArgumentException("Informe a atividade e a chave da operação."); return repository.Link(o,u,priority,r,wide,c); }
    public Task<Guid> Create(Guid o, Guid u, Guid priority, CreatePriorityActionRequest r, bool wide, CancellationToken c) { ActionPlanService.Validate(r.Title,r.EvidenceSummary,r.Priority); if(string.IsNullOrWhiteSpace(r.ExpectedOutcome)) throw new ArgumentException("Informe o resultado esperado."); if(r.CreatePlan==r.PlanId.HasValue) throw new ArgumentException("Selecione um plano existente ou crie um novo."); if(r.CreatePlan&&string.IsNullOrWhiteSpace(r.PlanTitle)) throw new ArgumentException("Informe o nome do novo plano."); if(string.IsNullOrWhiteSpace(r.CommandId)) throw new ArgumentException("Informe a chave da operação."); return repository.Create(o,u,priority,r,wide,c); }
}
public sealed class ActionProgressService(IActionItemRepository repository) { public Task Update(Guid o, Guid u, Guid id, bool wide, ProgressActionRequest r, CancellationToken c) { if (r.ProgressPercent is < 0 or > 99) throw new ArgumentOutOfRangeException(nameof(r.ProgressPercent), "O acompanhamento aceita de 0 a 99%. Use Concluir para registrar 100%."); return repository.UpdateProgress(o,u,id,wide,r,c); } public Task Block(Guid o, Guid u, Guid id, bool wide, TransitionActionRequest r, CancellationToken c) { ValidateReason(r); return repository.Block(o,u,id,wide,r,c); } public Task Resume(Guid o, Guid u, Guid id, bool wide, TransitionActionRequest r, CancellationToken c) { ValidateReason(r); return repository.Resume(o,u,id,wide,r,c); } public Task Complete(Guid o, Guid u, Guid id, bool wide, CompleteActionRequest r, CancellationToken c) { if (string.IsNullOrWhiteSpace(r.Result) || r.Result.Trim().Length < 10) throw new ArgumentException("Descreva o resultado alcançado (mínimo de 10 caracteres)."); if (string.IsNullOrWhiteSpace(r.Evidence)) throw new ArgumentException("Evidência de conclusão é obrigatória."); return repository.Complete(o,u,id,wide,r,c); } private static void ValidateReason(TransitionActionRequest r) { if(string.IsNullOrWhiteSpace(r.Reason)||r.Reason.Trim().Length<3) throw new ArgumentException("Informe uma justificativa com ao menos 3 caracteres."); } }
public sealed class ActionRecommendationService(IRecommendationRepository repository) { public Task<IReadOnlyList<ActionRecommendationDto>> List(Guid o, CancellationToken c) => repository.List(o, c); public Task<Guid> Suggest(Guid o, Guid u, ActionRecommendationDto r, CancellationToken c) { if (string.IsNullOrWhiteSpace(r.Evidence) || string.IsNullOrWhiteSpace(r.Limitation)) throw new ArgumentException("Sugestões de IA exigem evidência e limitação."); return repository.Enqueue(o, u, r with { Status = "proposed" }, c); } }
public sealed class GenerateActionPlanFromDiagnosticUseCase(ActionPlanService service) { public Task<Guid> Execute(Guid o, Guid u, CreateActionPlanRequest r, CancellationToken c) => service.Create(o, u, false, r with { OriginType = "diagnostic" }, c); }
