public sealed class CreateActionFromAlertUseCase(ActionItemService s) { public Task<Guid> Execute(Guid o, Guid u, CreateActionItemRequest r, CancellationToken c) => s.Create(o, u, r with { OriginType = "alert" }, c); }
public sealed class CreateActionFromDecisionUseCase(ActionItemService s) { public Task<Guid> Execute(Guid o, Guid u, CreateActionItemRequest r, CancellationToken c) => s.Create(o, u, r with { OriginType = "decision" }, c); }
public sealed class UpdateActionProgressUseCase(ActionProgressService s) { public Task Execute(Guid o, Guid u, Guid id, bool wide, ProgressActionRequest r, CancellationToken c) => s.Update(o,u,id,wide,r,c); }
public sealed class CompleteActionUseCase(ActionProgressService s) { public Task Execute(Guid o, Guid u, Guid id, bool wide, CompleteActionRequest r, CancellationToken c) => s.Complete(o,u,id,wide,r,c); }
public sealed class BlockActionUseCase(ActionProgressService s) { public Task Execute(Guid o, Guid u, Guid id, bool wide, TransitionActionRequest r, CancellationToken c) => s.Block(o,u,id,wide,r,c); }
public sealed class ResumeActionUseCase(ActionProgressService s) { public Task Execute(Guid o, Guid u, Guid id, bool wide, TransitionActionRequest r, CancellationToken c) => s.Resume(o,u,id,wide,r,c); }
